import{_ as t,o as i,c as n,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"CDS Infernalis (Day 1) -- Community && Governance","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- Community && Governance","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-06T00:00:00.000Z","tags":["Ceph","分布式存储","项目治理","用户委员会","自我治理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_Community_Governance.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_Community_Governance.md","lastUpdated":1780459816000}'),e={name:"posts/2015/CDS_Infernalis_Day_1_--_Community_Governance.md"};function o(s,l,a,p,_,g){return i(),n("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph 项目治理讨论及 SEF 用户委员会更新</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 项目领导 Sage、SEF 用户委员会主席 Eric、其他 Ceph 社区成员</p><p><strong>会议内容</strong>：</p><p><strong>一、SEF 用户委员会更新</strong></p><ul><li>SEF 用户委员会由 Sage 创立，旨在让用户对 Ceph 社区拥有实际的控制权。</li><li>用户委员会负责发布说明、组织会议等活动，是 Ceph 社区的重要组成部分。</li><li>Eric 目前担任 SEF 用户委员会主席，负责推动委员会的发展。</li></ul><p><strong>二、Ceph 项目治理</strong></p><ul><li>Ceph 项目的治理结构将包括董事会、技术委员会和用户委员会。</li><li><strong>董事会</strong>：负责社区推广、宣传、营销、品牌管理、冲突解决等。</li><li><strong>技术委员会</strong>：由组件技术负责人组成，负责技术决策和实现。</li><li><strong>用户委员会</strong>：负责用户需求、反馈和建议，并参与项目决策。</li><li><strong>项目领导</strong>：负责制定项目方向，并协调各个委员会的工作。</li><li><strong>其他角色</strong>：包括执行董事、学术联络人等。</li></ul><p><strong>三、自我治理</strong></p><ul><li>自我治理的目标是建立一个开放、参与式、透明的治理结构。</li><li>强调透明度，确保所有决策都在公共场合进行并记录在案。</li><li>鼓励社区成员参与治理，并提供反馈和建议。</li></ul><p><strong>四、其他讨论</strong></p><ul><li><strong>IP 管理和品牌政策</strong>：Ceph 项目将建立一个 IP 管理和品牌政策，以确保 Ceph 版权和品牌得到妥善管理。</li><li><strong>社区资源</strong>：Red Hat 将为社区提供更多资源，包括测试实验室、硬件等。</li><li><strong>用户委员会发展</strong>：将推动用户委员会的发展，并赋予其更多职责。</li></ul><p><strong>五、后续行动计划</strong></p><ul><li>在 Ceph Ether pad 上发布治理结构和商标政策的文档，供社区成员讨论和反馈。</li><li>推动自我治理的实施，确保社区有更强的代表性和参与度。</li></ul><p><strong>六、关键点</strong></p><ul><li>Ceph 项目治理结构将更加开放和透明。</li><li>社区成员将参与治理，并提供反馈和建议。</li><li>Red Hat 将为社区提供更多资源和支持。</li></ul><p><strong>七、关键词</strong></p><ul><li>Ceph</li><li>治理</li><li>自我治理</li><li>用户委员会</li><li>董事会</li><li>技术委员会</li><li>IP 管理</li><li>品牌政策</li><li>社区资源</li></ul>',19)])])}const c=t(e,[["render",o]]);export{C as __pageData,c as default};
